@test("base types")
def _():
    cases = {"int": "c_int", "unsigned int": "c_uint", "unsigned": "c_uint", "double": "c_double", "size_t": "c_size_t",
             "uint8_t": "c_uint8", "int64_t": "c_int64", "unsigned long long": "c_ulonglong", "bool": "c_bool",
             "void": "None", "const int": "c_int", "  unsigned   char ": "c_ubyte", "wchar_t": "c_wchar", "char": "c_char"}
    for c, py in cases.items():
        check_eq(ctypes_name(c), py)

@test("pointers")
def _():
    cases = {"const char *": "c_char_p", "char*": "c_char_p", "const wchar_t*": "c_wchar_p", "void *": "c_void_p",
             "int*": "POINTER(c_int)", "double **": "POINTER(POINTER(c_double))", "char **": "POINTER(c_char_p)",
             "void**": "POINTER(c_void_p)", "struct point": "point", "const struct point *": "POINTER(point)",
             "uint8_t * *": "POINTER(POINTER(c_uint8))"}
    for c, py in cases.items():
        check_eq(ctypes_name(c), py)

@test("types that are refused")
def _():
    for bad in ("long", "unsigned long", "string", "", "*", "int * x", "struct", "struct 9a"):
        check_raises(ValueError, ctypes_name, bad)

@test("prototypes")
def _():
    check_eq(parse_prototype("int32_t compress_block(const uint8_t *input, size_t length, uint8_t *output, size_t capacity);"),
             ("c_int32", "compress_block", ["POINTER(c_uint8)", "c_size_t", "POINTER(c_uint8)", "c_size_t"]))
    check_eq(parse_prototype("size_t strlen(const char *s)"), ("c_size_t", "strlen", ["c_char_p"]))
    check_eq(parse_prototype("const char *version(void);"), ("c_char_p", "version", []))
    check_eq(parse_prototype("char* name ( );"), ("c_char_p", "name", []))
    check_eq(parse_prototype("void free_rect(struct rect *r);"), ("None", "free_rect", ["POINTER(rect)"]))

@test("parameters without names, arrays and keywords")
def _():
    check_eq(parse_prototype("double pow(double, double);"), ("c_double", "pow", ["c_double", "c_double"]))
    check_eq(parse_prototype("int sum(const int values[], unsigned int count);"), ("c_int", "sum", ["POINTER(c_int)", "c_uint"]))
    check_eq(parse_prototype("int fill(uint8_t buffer[16], unsigned);"), ("c_int", "fill", ["POINTER(c_uint8)", "c_uint"]))
    check_eq(parse_prototype("bool is_valid(struct point p);"), ("c_bool", "is_valid", ["point"]))

@test("not declarations")
def _():
    for bad in ("int x;", "foo();", "int (int a);", "int f(long n);", "int f(int a) extra;"):
        check_raises(ValueError, parse_prototype, bad)

